const express=require('express'),router=express.Router(),playersController=require('../controllers/playersController.min.js'),{onlyAdminAuth,requireAuth}=require('../middlewares/auth.min.js'),cache=require('../route_cache.js'),ONE_HOUR=3600;router.post('/players',onlyAdminAuth,playersController.create_player);router.get('/players',requireAuth,cache(ONE_HOUR),playersController.get_players);router.get('/players/:id',onlyAdminAuth,playersController.get_single_player);router.delete('/players/:id',onlyAdminAuth,playersController.delete_player);router.put('/players/:id',onlyAdminAuth,playersController.update_player);module.exports=router; 